-- ─── 1. ROLES ──────────────────────────────────────────────────────────────
-- NOLOGIN, exactly like migrations/20260808070000_claude_ro_select_only.sql: role LIFECYCLE
-- (login, password) belongs to the platform (CNPG `managed.roles`), and this repository is
-- public. NOBYPASSRLS on every one of them is the invariant gate G-6 asserts -- a role
-- attribute is not scoped to a table, so BYPASSRLS bypasses on tables it was never meant
-- to. NOINHERIT so a granted persona is reached only by an explicit SET ROLE.
-- Idempotent, and it degrades the way the house pattern degrades: a migration user without
-- CREATEROLE gets a NOTICE, not a failure.

DO $$
DECLARE r text;
BEGIN
  FOREACH r IN ARRAY ARRAY['admin_role', 'customer_role', 'migrator', 'projector_order', 'restaurant_role', 'rider_role'] LOOP
    IF NOT EXISTS (SELECT FROM pg_catalog.pg_roles WHERE rolname = r) THEN
      BEGIN
        EXECUTE format('CREATE ROLE %I NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOBYPASSRLS NOINHERIT', r);
      EXCEPTION WHEN insufficient_privilege THEN
        RAISE NOTICE 'role % not created (this user lacks CREATEROLE) -- create it out of band and re-run', r;
      END;
    END IF;
  END LOOP;
END $$;

-- ─── 2. OWNERSHIP ──────────────────────────────────────────────────────────
-- The business schema is owned by the declared owner of its database
